import React, { useEffect } from 'react';
import { useLocation } from 'react-router-dom';

interface SEOProps {
  title?: string;
  description?: string;
  image?: string;
  url?: string;
  type?: 'website' | 'article' | 'webapp';
  verse?: {
    book?: string;
    chapter?: number;
    verse?: number;
    text?: string;
  };
  keywords?: string[];
  author?: string;
}

/**
 * SEO Component for dynamic meta tags and structured data
 * Makes the site AI-friendly by providing rich, structured information
 */
const SEO: React.FC<SEOProps> = ({
  title = 'Revelationary Online - Free Bible Study App',
  description = 'An Online Bible Study App for Christians and followers of Jesus Christ. Study the Bible with verse highlights, comments, media insights, and community discussions. Available in English, Chinese (Simplified), and German.',
  image = 'https://revelationary.online/logo512.png',
  url,
  type = 'website',
  verse,
  keywords = ['Bible study', 'Bible app', 'Christian app', 'Bible commentary', 'Bible reading', 'Bible study tools', 'KJV Bible', 'Chinese Bible', 'CUV Bible', 'German Bible', 'LUT Bible', 'Lutherbibel', 'Bible verses', 'scripture study'],
  author = 'Revelationary Team'
}) => {
  const location = useLocation();
  const baseUrl = 'https://revelationary.online';
  const currentUrl = url || `${baseUrl}${location.pathname}${location.hash}`;
  
  // Enhanced description with verse context if available
  const enhancedDescription = verse 
    ? `${description} Currently viewing: ${verse.book} ${verse.chapter}:${verse.verse} - "${verse.text?.substring(0, 100)}..."`
    : description;

  // Enhanced title with verse context if available
  const enhancedTitle = verse
    ? `${verse.book} ${verse.chapter}:${verse.verse} | ${title}`
    : title;

  // Generate structured data
  const generateStructuredData = () => {
    const schemas: any[] = [];

    // Main WebApplication schema
    schemas.push({
      '@context': 'https://schema.org',
      '@type': 'WebApplication',
      'name': 'Revelationary Online',
      'alternateName': 'Revelationary',
      'description': 'A free, comprehensive Bible study application with verse highlighting, community comments, media insights, reading progress tracking, and multilingual support (English, Chinese, German).',
      'url': baseUrl,
      'applicationCategory': 'EducationalApplication',
      'operatingSystem': 'Web Browser',
      'offers': {
        '@type': 'Offer',
        'price': '0',
        'priceCurrency': 'USD'
      },
      'featureList': [
        'Bible verse highlighting',
        'Community comments and discussions',
        'Reading progress tracking',
        'Multilingual support (English, Chinese, German)',
        'Verse search',
        'Bookmarks',
        'Media and science insights',
        'Linked verses'
      ],
      'browserRequirements': 'Requires JavaScript. Requires HTML5.',
      'inLanguage': ['en', 'zh-Hans'],
      'isAccessibleForFree': true,
      'publisher': {
        '@type': 'Organization',
        'name': 'Revelationary',
        'url': 'https://revelationary.org'
      }
    });

    // WebSite schema with search
    schemas.push({
      '@context': 'https://schema.org',
      '@type': 'WebSite',
      'name': 'Revelationary Online',
      'url': baseUrl,
      'description': 'Free Bible study app with advanced features for studying scripture',
      'inLanguage': ['en', 'zh-Hans', 'de'],
      'potentialAction': {
        '@type': 'SearchAction',
        'target': {
          '@type': 'EntryPoint',
          'urlTemplate': `${baseUrl}/?search={search_term_string}`
        },
        'query-input': 'required name=search_term_string'
      }
    });

    // If viewing a specific verse, add Book schema
    if (verse && verse.book && verse.chapter && verse.verse) {
      schemas.push({
        '@context': 'https://schema.org',
        '@type': 'Book',
        'name': verse.book,
        'description': `Bible Study: ${verse.book} Chapter ${verse.chapter}, Verse ${verse.verse}`,
        'bookEdition': 'King James Version / Chinese Union Version / Lutherbibel',
        'inLanguage': 'en',
        'isPartOf': {
          '@type': 'Book',
          'name': 'The Holy Bible'
        },
        'about': {
          '@type': 'Thing',
          'name': 'Bible Study',
          'description': verse.text || 'Bible verse'
        }
      });

      // Article schema for verse discussions
      schemas.push({
        '@context': 'https://schema.org',
        '@type': 'Article',
        'headline': `${verse.book} ${verse.chapter}:${verse.verse} - Bible Study`,
        'description': `Study and discuss ${verse.book} ${verse.chapter}:${verse.verse} with community insights and commentary`,
        'url': currentUrl,
        'author': {
          '@type': 'Organization',
          'name': 'Revelationary Community'
        },
        'publisher': {
          '@type': 'Organization',
          'name': 'Revelationary',
          'logo': {
            '@type': 'ImageObject',
            'url': `${baseUrl}/logo512.png`
          }
        },
        'about': {
          '@type': 'CreativeWork',
          'name': verse.book,
          'text': verse.text
        }
      });
    }

    // SoftwareApplication schema (enhanced)
    schemas.push({
      '@context': 'https://schema.org',
      '@type': 'SoftwareApplication',
      'name': 'Revelationary Online',
      'applicationCategory': 'EducationalApplication',
      'operatingSystem': 'Web',
      'offers': {
        '@type': 'Offer',
        'price': '0',
        'priceCurrency': 'USD',
        'availability': 'https://schema.org/InStock'
      },
      'aggregateRating': {
        '@type': 'AggregateRating',
        'ratingValue': '5',
        'ratingCount': '1',
        'bestRating': '5',
        'worstRating': '1'
      },
      'description': 'Free Bible study application with verse highlighting, comments, reading progress, and bilingual support',
      'featureList': [
        'Interactive Bible reading',
        'Verse highlighting and bookmarks',
        'Community comments and replies',
        'Reading progress tracking',
        'Multi-language support',
        'Verse search',
        'Media insights'
      ]
    });

    // BreadcrumbList schema
    const breadcrumbs = [
      { name: 'Home', url: baseUrl },
      { name: title, url: currentUrl }
    ];
    if (verse && verse.book) {
      breadcrumbs.splice(1, 0, { name: verse.book, url: `${baseUrl}/#/${verse.book}` });
    }

    schemas.push({
      '@context': 'https://schema.org',
      '@type': 'BreadcrumbList',
      'itemListElement': breadcrumbs.map((item, index) => ({
        '@type': 'ListItem',
        'position': index + 1,
        'name': item.name,
        'item': item.url
      }))
    });

    // FAQPage schema for common questions
    schemas.push({
      '@context': 'https://schema.org',
      '@type': 'FAQPage',
      'mainEntity': [
        {
          '@type': 'Question',
          'name': 'Is Revelationary Online free?',
          'acceptedAnswer': {
            '@type': 'Answer',
            'text': 'Yes, Revelationary Online is completely free to use. All features including verse highlighting, comments, bookmarks, and reading progress tracking are available at no cost.'
          }
        },
        {
          '@type': 'Question',
          'name': 'What Bible translations are available?',
          'acceptedAnswer': {
            '@type': 'Answer',
            'text': 'Revelationary Online supports King James Version (KJV) in English, Chinese Union Version (CUV) in Simplified Chinese, and Lutherbibel (LUT) in German.'
          }
        },
        {
          '@type': 'Question',
          'name': 'Can I comment on Bible verses?',
          'acceptedAnswer': {
            '@type': 'Answer',
            'text': 'Yes, you can comment on any Bible verse, reply to other comments, and engage in discussions with the community.'
          }
        },
        {
          '@type': 'Question',
          'name': 'How do I track my Bible reading progress?',
          'acceptedAnswer': {
            '@type': 'Answer',
            'text': 'The app automatically tracks your reading progress as you navigate through chapters. You can mark chapters as read to track your progress through the entire Bible.'
          }
        }
      ]
    });

    return schemas;
  };

  const structuredData = generateStructuredData();

  useEffect(() => {
    // Helper function to update or create meta tags
    const updateMetaTag = (name: string, content: string, property?: boolean) => {
      const attribute = property ? 'property' : 'name';
      let element = document.querySelector(`meta[${attribute}="${name}"]`) as HTMLMetaElement;
      if (!element) {
        element = document.createElement('meta');
        element.setAttribute(attribute, name);
        document.head.appendChild(element);
      }
      element.setAttribute('content', content);
    };

    // Update document title
    document.title = enhancedTitle;

    // Update basic meta tags
    updateMetaTag('description', enhancedDescription);
    updateMetaTag('keywords', keywords.join(', '));
    updateMetaTag('author', author);
    updateMetaTag('robots', 'index, follow, max-image-preview:large, max-snippet:-1, max-video-preview:-1');
    updateMetaTag('googlebot', 'index, follow');
    updateMetaTag('bingbot', 'index, follow');
    updateMetaTag('AI', 'true');
    updateMetaTag('content-type', 'text/html; charset=utf-8');

    // Update Open Graph tags
    updateMetaTag('og:type', type, true);
    updateMetaTag('og:url', currentUrl, true);
    updateMetaTag('og:title', enhancedTitle, true);
    updateMetaTag('og:description', enhancedDescription, true);
    updateMetaTag('og:image', image, true);
    updateMetaTag('og:locale', 'en_US', true);
    updateMetaTag('og:locale:alternate', 'zh_CN', true);
    updateMetaTag('og:locale:alternate', 'de_DE', true);
    updateMetaTag('og:site_name', 'Revelationary Online', true);

    // Update Twitter tags
    updateMetaTag('twitter:card', 'summary_large_image');
    updateMetaTag('twitter:url', currentUrl);
    updateMetaTag('twitter:title', enhancedTitle);
    updateMetaTag('twitter:description', enhancedDescription);
    updateMetaTag('twitter:image', image);

    // Update canonical URL
    let canonical = document.querySelector('link[rel="canonical"]') as HTMLLinkElement;
    if (!canonical) {
      canonical = document.createElement('link');
      canonical.setAttribute('rel', 'canonical');
      document.head.appendChild(canonical);
    }
    canonical.setAttribute('href', currentUrl);

    // Add alternate language links
    const addAlternateLink = (hreflang: string, href: string) => {
      let link = document.querySelector(`link[rel="alternate"][hreflang="${hreflang}"]`) as HTMLLinkElement;
      if (!link) {
        link = document.createElement('link');
        link.setAttribute('rel', 'alternate');
        link.setAttribute('hreflang', hreflang);
        document.head.appendChild(link);
      }
      link.setAttribute('href', href);
    };

    addAlternateLink('en', currentUrl);
    addAlternateLink('zh-Hans', currentUrl);
    addAlternateLink('de', currentUrl);
    addAlternateLink('x-default', currentUrl);

    // Remove old structured data scripts
    const oldScripts = document.querySelectorAll('script[data-seo-structured-data]');
    oldScripts.forEach(script => script.remove());

    // Add new structured data
    structuredData.forEach((schema, index) => {
      const script = document.createElement('script');
      script.type = 'application/ld+json';
      script.setAttribute('data-seo-structured-data', 'true');
      script.textContent = JSON.stringify(schema, null, 2);
      document.head.appendChild(script);
    });

    // Cleanup function
    return () => {
      // Optionally clean up on unmount if needed
    };
  }, [enhancedTitle, enhancedDescription, currentUrl, type, image, keywords, author, structuredData]);

  return null; // This component doesn't render anything
};

export default SEO;

