  // Fetch IQ Bible data for a specific section on demand
  const handleSectionExpand = async (
    section: 'originalText'
  ) => {
    if (selectedVerse.length === 0) {
      return;
    }

    // Don't fetch if already loaded or currently loading
    if (iqBibleData[section] !== undefined || loadingIqBible[section]) {
      return;
    }

    const verse = selectedVerse[0];
    const verseId = convertToIqBibleVerseId(verse.book, verse.chapter, verse.verse);

    if (!verseId) {
      console.error('Failed to convert verse to IQ Bible verseId format');
      return;
    }

    // Set loading state for this section
    setLoadingIqBible((prev) => ({ ...prev, [section]: true }));

    try {
      // Map translation code to language parameter for API
      const languageMap: Record<string, string> = {
        'kjv': 'english',
        'cuv': 'chinese',
        'lut': 'german',
        'es-rv09': 'spanish',
      };
      const language = languageMap[translation] || 'english';

      let result: any;
      switch (section) {
        case 'originalText': {
          // Use static Strong's data instead of RapidAPI
          try {
            console.log(`Fetching Hebrew words for: ${verse.book} ${verse.chapter}:${verse.verse}`);
            const hebrewWords = await fetchHebrewWordsForVerse(
              verse.book,
              verse.chapter,
              verse.verse
            );
            
            console.log(`Found ${hebrewWords.length} Hebrew words`);
            
            if (hebrewWords.length === 0) {
              console.warn(`No Hebrew words found for ${verse.book} ${verse.chapter}:${verse.verse}`);
              result = null;
            } else {
              // Convert VerseWord[] to OriginalTextWord[] format for compatibility
              // Map translation code to Strong's language code: kjv -> en, cuv -> zh, lut -> de, es-rv09 -> es
              const langMap: Record<string, string> = {
                'kjv': 'en',
                'cuv': 'zh',
                'lut': 'de',
                'es-rv09': 'es',
              };
              const strongsLang = langMap[translation] || 'en';
              
              result = hebrewWords.map((word, index) => {
                // Get translated definition based on user's language
                const translatedDefinition = getStrongsDefinition(word.entry, strongsLang);
                
                return {
                  id: `word-${index}`,
                  verseID: verseId || '',
                  book: verse.book,
                  chapter: String(verse.chapter),
                  verse: String(verse.verse),
                  word: word.hebrew,
                  strongs: word.strongsNumber,
                  pronun: word.entry.pronunciation ? JSON.stringify({ dic: word.entry.pronunciation }) : undefined,
                  glossary: translatedDefinition, // Use translated definition
                  orig_order: String(word.position),
                  connected: '',
                  parashah: '',
                  notes: word.entry.kjvTranslation,
                  entry: word.entry, // Include full entry for translation lookup
                };
              });
              console.log(`Converted ${result.length} words to OriginalTextWord format`);
            }
          } catch (error) {
            console.error('Error fetching Hebrew words:', error);
            result = null;
          }
          break;
        }
        default:
          return;
      }

      setIqBibleData((prev) => ({
        ...prev,
        [section]: result || null,
      }));
    } catch (error) {
      console.error(`Error fetching IQ Bible ${section}:`, error);
      setIqBibleData((prev) => ({
        ...prev,
        [section]: null,
      }));
    } finally {
      setLoadingIqBible((prev) => ({ ...prev, [section]: false }));
    }
  };

