import React, { useState, useEffect, useMemo } from 'react';
import Joyride, { CallBackProps, Step, STATUS } from 'react-joyride';
import Cookies from 'js-cookie';
import { User } from 'firebase/auth';
import { useTheme } from '@mui/material/styles';
import { useTranslation } from '../../hooks/useTranslation';

interface DashboardTourProps {
  user: User | null;
  wpToken: string | null;
}

const DashboardTour: React.FC<DashboardTourProps> = ({ user, wpToken }) => {
  const theme = useTheme();
  const { t, language } = useTranslation(); // language ensures re-render on locale change
  const [run, setRun] = useState(false);
  const [tourStarted, setTourStarted] = useState(false);
  
  // Memoize steps to update when language changes
  const steps = useMemo<Step[]>(() => [
    {
      target: '.verse__selected .verse__text',
      content: String(t('tour.selectVerse.content')),
      disableBeacon: true,
      placement: 'top',
      title: String(t('tour.selectVerse.title'))
    }
  ], [t, language]);

  useEffect(() => {
    // Check if the user has seen the tour before
    const checkTourStatus = () => {
      // Check for development mode reset parameter
      const urlParams = new URLSearchParams(window.location.search);
      const resetTour = urlParams.get('resetTour');

      // If resetTour is explicitly set to 'true', run the tour regardless
      if (resetTour === 'true') {
        // Dispatch event to select verse first, then start tour after a delay
        const event = new CustomEvent('tourStarted', { detail: { selectVerse: true } });
        window.dispatchEvent(event);
        setTimeout(() => setRun(true), 500); // Wait for verse to be selected
        return;
      }

      // Otherwise check cookies/localStorage
      if (user && user.uid) {
        // For logged-in users, check cookies or localStorage
        const hasSeenTourCookie = Cookies.get(`dashboardTourCompleted_${user.uid}`);
        const hasSeenTourLocal = localStorage.getItem(`dashboardTourCompleted_${user.uid}`);
        
        // Only start the tour if both cookie and localStorage are missing
        if (!hasSeenTourCookie && !hasSeenTourLocal) {
          // Dispatch event to select verse first, then start tour after a delay
          const event = new CustomEvent('tourStarted', { detail: { selectVerse: true } });
          window.dispatchEvent(event);
          setTimeout(() => setRun(true), 500); // Wait for verse to be selected
        } else {
          setRun(false);
        }
      } else {
        // For anonymous users or when not logged in
        const hasSeenTourCookie = Cookies.get('dashboardTourCompleted');
        const hasSeenTourLocal = localStorage.getItem('dashboardTourCompleted');
        
        // Only start the tour if both cookie and localStorage are missing
        if (!hasSeenTourCookie && !hasSeenTourLocal) {
          // Dispatch event to select verse first, then start tour after a delay
          const event = new CustomEvent('tourStarted', { detail: { selectVerse: true } });
          window.dispatchEvent(event);
          setTimeout(() => setRun(true), 500); // Wait for verse to be selected
        } else {
          setRun(false);
        }
      }
    };

    // Add a slight delay to ensure cookies/localStorage are read properly
    setTimeout(checkTourStatus, 100);
  }, [user]);

  const handleJoyrideCallback = (data: CallBackProps) => {
    const { status, type, action } = data;
    const finishedStatuses: string[] = [STATUS.FINISHED, STATUS.SKIPPED];

    // Track when tour actually starts
    if (type === 'tour:start' || type === 'step:after') {
      setTourStarted(true);
      // Dispatch custom event to trigger verse selection for the tour
      if (type === 'tour:start') {
        const event = new CustomEvent('tourStarted', { detail: { selectVerse: true } });
        window.dispatchEvent(event);
      }
    }

    // Only mark as completed if:
    // 1. The tour actually started (was visible to user)
    // 2. The tour status is FINISHED or SKIPPED
    // 3. This prevents premature completion if target element isn't found
    if (finishedStatuses.includes(status) && tourStarted) {
      setRun(false);
      
      // Save that the user has completed the tour
      if (user && user.uid) {
        // Save in cookie for logged-in users with a user ID
        Cookies.set(`dashboardTourCompleted_${user.uid}`, 'true', { expires: 365, path: '/' });
        localStorage.setItem(`dashboardTourCompleted_${user.uid}`, 'true');
      } else {
        // Save in cookie for anonymous users
        Cookies.set('dashboardTourCompleted', 'true', { expires: 365, path: '/' });
        localStorage.setItem('dashboardTourCompleted', 'true');
      }

      console.log('Tour completed - cookie status:', user?.uid ? 
        Cookies.get(`dashboardTourCompleted_${user.uid}`) : 
        Cookies.get('dashboardTourCompleted'));
    } else if (finishedStatuses.includes(status) && !tourStarted) {
      // If tour finishes without starting (target not found), don't mark as completed
      console.log('Tour finished without starting - target element may not be found. Not marking as completed.');
      setRun(false);
    }
  };

  return (
    <Joyride
      callback={handleJoyrideCallback}
      continuous={false}
      hideCloseButton
      run={run}
      scrollToFirstStep
      showProgress={false}
      showSkipButton
      locale={{
        last: String(t('tour.buttons.complete')),
        next: String(t('tour.buttons.next')),
        skip: String(t('tour.buttons.skip')),
        back: String(t('tour.buttons.back'))
      }}
      steps={steps}
      styles={{
        options: {
          backgroundColor: theme.palette.mode === 'dark' ? '#1d1d1d' : '#ffffff',
          primaryColor: theme.palette.primary.main,
          textColor: theme.palette.text.primary,
          arrowColor: theme.palette.mode === 'dark' ? '#1d1d1d' : '#ffffff',
          zIndex: 10000,
        },
        tooltip: {
          backgroundColor: theme.palette.mode === 'dark' ? '#1d1d1d' : '#ffffff',
          color: theme.palette.text.primary,
          fontSize: '14px',
        },
        tooltipFooter: {
          marginTop: '14px',
        },
        // This styles the spotlight highlighting the element
        spotlight: {
          backgroundColor: 'rgba(0, 0, 0, 0.4)',
        },
        tooltipContainer: {
          textAlign: 'left',
        },
        tooltipTitle: {
          fontSize: '16px',
          fontWeight: 'bold',
          marginLeft: '0.5rem',
          color: theme.palette.primary.main,
        },
        buttonNext: {
          backgroundColor: theme.palette.mode === 'light' ? '#ffffff' : '#212121',
          color: theme.palette.mode === 'dark' ? '#ffffff' : '#212121'
        },
        buttonBack: {
          color: '#A1A1A1',
        },
        buttonSkip: {
          color: theme.palette.text.secondary,
        },
      }}
    />
  );
};

export default DashboardTour;
