/**
 * Utility for handling optimized image formats (WebP with PNG fallback)
 */

/**
 * Check if browser supports WebP format
 */
export function supportsWebP(): boolean {
  if (typeof window === 'undefined') return false;
  
  const canvas = document.createElement('canvas');
  canvas.width = 1;
  canvas.height = 1;
  return canvas.toDataURL('image/webp').indexOf('data:image/webp') === 0;
}

/**
 * Get the best image format based on browser support
 * Returns WebP path if supported, otherwise returns PNG path
 * 
 * @param webpPath - Path to WebP version of image
 * @param pngPath - Path to PNG fallback version
 * @returns The appropriate image path
 */
export function getOptimizedImagePath(webpPath: string, pngPath: string): string {
  return supportsWebP() ? webpPath : pngPath;
}

/**
 * Get CSS background-image with WebP support and fallback
 * Returns a CSS string that can be used with backgroundImage property
 * 
 * @param webpPath - Path to WebP version
 * @param pngPath - Path to PNG fallback
 * @returns CSS background-image string
 */
export function getOptimizedBackgroundImage(webpPath: string, pngPath: string): string {
  if (supportsWebP()) {
    return `url(${webpPath})`;
  }
  return `url(${pngPath})`;
}
