import { useEffect, useState, useCallback, useMemo } from 'react';
import { useTranslation as useI18nTranslation } from 'react-i18next';
import Cookies from 'js-cookie';

/**
 * Custom hook that syncs i18n locale with the translation value from localStorage/cookies
 * Maps: kjv -> en, cuv -> zh-hans
 * Returns t function and language to force re-renders
 */
export const useTranslation = () => {
  const { t, i18n } = useI18nTranslation();
  const [language, setLanguage] = useState(i18n.language);

  // Function to update locale from storage
  const updateLocale = useCallback(() => {
    const translation = Cookies.get('translation') || localStorage.getItem('translation') || 'kjv';
    let locale = 'en';
    if (translation === 'cuv') {
      locale = 'zh-hans';
    } else if (translation === 'lut') {
      locale = 'de';
    } else if (translation === 'es-rv09') {
      locale = 'es';
    }
    
    // Update state immediately if locale is different
    if (language !== locale) {
      console.log('Updating language state from', language, 'to', locale);
      setLanguage(locale);
    }
    
    // Update i18n if it doesn't match
    if (i18n.language !== locale) {
      console.log('Updating i18n locale from', i18n.language, 'to', locale);
      i18n.changeLanguage(locale).then(() => {
        console.log('i18n.changeLanguage completed, new language:', i18n.language);
        // Double-check state matches
        setLanguage(locale);
      }).catch((err: any) => {
        console.error('Error changing language:', err);
      });
    }
  }, [i18n, language]);

  // Listen for i18n language changes - this is the primary way components re-render
  useEffect(() => {
    const handleLanguageChanged = (lng: string) => {
      console.log('i18n languageChanged event:', lng);
      // CRITICAL: Update state immediately to force ALL components using this hook to re-render
      setLanguage(lng);
      console.log('State updated to:', lng, 'i18n.language is now:', i18n.language);
    };
    
    // Subscribe to language changes
    i18n.on('languageChanged', handleLanguageChanged);
    
    // Set initial language from i18n
    const currentLang = i18n.language;
    setLanguage(currentLang);
    console.log('Initial language set to:', currentLang);
    
    return () => {
      i18n.off('languageChanged', handleLanguageChanged);
    };
  }, [i18n]);

  // Watch localStorage and cookies for changes
  useEffect(() => {
    // Initial check
    updateLocale();

    // Check frequently for localStorage changes (same-tab storage events don't fire)
    const interval = setInterval(() => {
      updateLocale();
    }, 100); // Check every 100ms

    // Listen for storage events (cross-tab only)
    const handleStorageChange = (e: StorageEvent) => {
      if (e.key === 'translation' || e.key === null) {
        console.log('Storage event detected');
        updateLocale();
      }
    };
    
    if (typeof window !== 'undefined') {
      window.addEventListener('storage', handleStorageChange);
    }

    // Listen for custom translation change events
    const handleTranslationChange = (e?: Event) => {
      console.log('Custom translationChanged event detected', e instanceof CustomEvent ? e.detail : '');
      updateLocale();
    };
    
    if (typeof window !== 'undefined') {
      window.addEventListener('translationChanged', handleTranslationChange as EventListener);
    }

    return () => {
      clearInterval(interval);
      if (typeof window !== 'undefined') {
        window.removeEventListener('storage', handleStorageChange);
        window.removeEventListener('translationChanged', handleTranslationChange as EventListener);
      }
    };
  }, [updateLocale]);

  // Return t function and language - language will trigger re-renders when it changes
  // Force re-render by including language in the return value
  // Components should use language in their dependency arrays or as a key
  // IMPORTANT: Use getFixedT to get a translation function bound to the current language
  // This ensures we always get translations for the correct language
  // Use useMemo to recreate the function when language changes
  const wrappedT = useMemo(() => {
    // Return a function that directly uses i18n.t with the current language
    // This ensures we always get translations for the correct language
    return (key: string, options?: any) => {
      const currentLang = language || i18n.language;
      
      // Removed verbose console logging to prevent infinite loops
      // Uncomment below for debugging if needed:
      // if (process.env.NODE_ENV === 'development' && !key.startsWith('books.')) {
      //   console.log('wrappedT called with key:', key, 'language:', currentLang);
      // }
      
      // Get the resource bundle for the current language
      // This ensures we always get translations for the correct language
      const resources = i18n.getResourceBundle(currentLang, 'translation');
      
      if (resources) {
        // Navigate through the key path (e.g., "common.translations" -> resources.common.translations)
        const keys = key.split('.');
        let value: any = resources;
        
        for (const k of keys) {
          if (value && typeof value === 'object' && k in value) {
            value = value[k];
          } else {
            // Key not found, fall back to i18n.t
            if (process.env.NODE_ENV === 'development') {
              console.warn(`Translation key "${key}" not found in ${currentLang}, falling back to i18n.t`);
            }
            return i18n.t(key, { ...options, ns: 'translation', lng: currentLang });
          }
        }
        
        // If we found a string value, return it (with interpolation if options provided)
        if (typeof value === 'string') {
          // Simple interpolation for options
          if (options && typeof options === 'object') {
            let result = value;
            for (const [optKey, optValue] of Object.entries(options)) {
              result = result.replace(new RegExp(`{{${optKey}}}`, 'g'), String(optValue));
            }
            return result;
          }
          return value;
        }
      }
      
      // Fallback to i18n.t if resource bundle access fails
      if (process.env.NODE_ENV === 'development') {
        console.warn(`Resource bundle not found for ${currentLang}, using i18n.t fallback`);
      }
      return i18n.t(key, { ...options, ns: 'translation', lng: currentLang });
    };
  }, [i18n, language]);

  return { 
    t: wrappedT, 
    i18n, 
    language, 
    ready: i18n.isInitialized 
  };
};
